// quickget-catalog: Go resolver for the quickget OS catalog.
// Reads catalog/data/catalog.json (generated by tools/dump-catalog.sh)
// and answers releases/editions/arch/url queries identically to the
// Bash catalog functions. For OSes whose Bash get_<os> is a scraper
// (dynamic URL), the JSON stores the last-resolved template; the
// catalog-health CI regenerates it nightly.
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/alesanfe/quickemu/tools/qelib"
)

type Entry struct {
	OS       string   `json:"os"`
	Releases []string `json:"releases"`
	Editions []string `json:"editions"`
	Arch     []string `json:"arch"`
	// URL is the get_<os> result template with %s placeholders for
	// release/edition where the Bash function interpolates them.
	URL     string `json:"url,omitempty"`
	ISO     string `json:"iso,omitempty"`
	HashURL string `json:"hash_url,omitempty"`
	HashRE  string `json:"hash_re,omitempty"`
	// Scrape marks OSes whose URL must be re-resolved live — handled
	// natively by scrape() (mirrors the Bash get_<os> logic 1:1).
	Scrape bool `json:"scrape,omitempty"`
	// QArch marks templates dumped from get_ bodies that used
	// ${QEMU_ARCH} (x86_64/aarch64) instead of ${ARCH} (amd64/arm64).
	QArch bool `json:"qarch,omitempty"`

	// Classification metadata — lets consumers tell a maintained ISO
	// apart from a historical image, an ARM-only build or media that
	// needs credentials. Values are enum-like strings documented in
	// schemas/v1/catalog.schema.json; empty means unspecified.
	Status       string `json:"status,omitempty"`        // active|discontinued|archived|experimental
	ImageType    string `json:"image_type,omitempty"`    // iso|raw|qcow2|vhd|vmdk|floppy|kernel|zip|ova
	DownloadMode string `json:"download_mode,omitempty"` // direct|mirror|manual|authenticated|archived
	License      string `json:"license,omitempty"`       // redistributable|restricted|unknown
	BootMode     string `json:"boot_mode,omitempty"`     // bios|uefi|both|custom
	SupportLevel string `json:"support_level,omitempty"` // stable|community|experimental
}

// Meta is the classification view of an Entry returned by `meta`.
type Meta struct {
	OS           string   `json:"os"`
	Status       string   `json:"status,omitempty"`
	Arch         []string `json:"arch,omitempty"`
	ImageType    string   `json:"image_type,omitempty"`
	DownloadMode string   `json:"download_mode,omitempty"`
	License      string   `json:"license,omitempty"`
	BootMode     string   `json:"boot_mode,omitempty"`
	SupportLevel string   `json:"support_level,omitempty"`
}

func (e *Entry) meta() Meta {
	return Meta{OS: e.OS, Status: e.Status, Arch: e.Arch,
		ImageType: e.ImageType, DownloadMode: e.DownloadMode,
		License: e.License, BootMode: e.BootMode, SupportLevel: e.SupportLevel}
}

type Catalog struct {
	Generated string  `json:"generated"`
	Entries   []Entry `json:"entries"`
}

func loadCatalog(path string) (*Catalog, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var c Catalog
	if err := json.Unmarshal(b, &c); err != nil {
		return nil, err
	}
	return &c, nil
}

func find(c *Catalog, name string) *Entry {
	for i := range c.Entries {
		if c.Entries[i].OS == name {
			return &c.Entries[i]
		}
	}
	return nil
}

func catalogPath() string {
	if p := os.Getenv("QUICKEMU_CATALOG"); p != "" {
		return p
	}
	return qelib.DataFile("catalog", "data", "catalog.json")
}

func infoPath() string {
	if p := os.Getenv("QUICKEMU_INFO"); p != "" {
		return p
	}
	return filepath.Join(filepath.Dir(catalogPath()), "info.json")
}

func main() { os.Exit(run()) }

// catCmd handles one subcommand; args is the full argv after argv[0].
type catCmd func(cat *Catalog, args []string) int

var catCmds = map[string]catCmd{
	"list": cmdList, "releases": cmdReleases, "editions": cmdEditions,
	"arch": cmdArch, "url": cmdURL, "check": cmdCheck,
	"info": cmdInfo, "info-json": cmdInfoJSON, "trust": cmdTrust,
	"meta": cmdMeta,
}

// Every subcommand except list indexes args[1] — missing operand
// is a usage error, not a panic.
var needsOS = map[string]bool{
	"releases": true, "editions": true, "arch": true, "url": true,
	"check": true, "info": true, "info-json": true, "trust": true,
}

// relArgs unpacks the optional [release] [edition] [arch] tail shared
// by url/check/trust.
func relArgs(args []string) (release, edition, arch string) {
	arch = "amd64"
	if len(args) > 2 {
		release = args[2]
	}
	if len(args) > 3 {
		edition = args[3]
	}
	if len(args) > 4 {
		arch = args[4]
	}
	return
}

func run() int {
	args := os.Args[1:]
	if len(args) < 1 {
		fmt.Fprintln(os.Stderr, "usage: quickget-catalog <list|releases|editions|arch|url|check|info|info-json|trust|meta> <os> [release] [edition] [arch]")
		return 2
	}
	cat, err := loadCatalog(catalogPath())
	if err != nil {
		fmt.Fprintf(os.Stderr, "catalog: %v\n", err)
		return 1
	}
	if needsOS[args[0]] && len(args) < 2 {
		fmt.Fprintf(os.Stderr, "usage: quickget-catalog %s <os> [release] [edition] [arch]\n", args[0])
		return 2
	}
	if fn := catCmds[args[0]]; fn != nil {
		return fn(cat, args)
	}
	fmt.Fprintf(os.Stderr, "unknown subcommand %q\n", args[0])
	return 2
}

func cmdList(cat *Catalog, _ []string) int {
	for _, e := range cat.Entries {
		fmt.Println(e.OS)
	}
	return 0
}

func cmdReleases(cat *Catalog, args []string) int {
	{
		// releases <os> — static list, or live scrape for OSes whose
		// releases_<os>() resolved dynamically (pureos/rockylinux/slitaz).
		e := find(cat, args[1])
		if e == nil {
			return 1
		}
		rels := e.Releases
		if len(rels) == 0 {
			rels = scrapeReleases(e.OS)
		}
		fmt.Println(strings.Join(rels, " "))
	}
	return 0
}

func cmdEditions(cat *Catalog, args []string) int {
	{
		// editions <os> [release] — static list, or live scrape for
		// OSes whose editions_<os>() depends on the release (blackarch).
		e := find(cat, args[1])
		if e == nil {
			return 1
		}
		if len(e.Editions) > 0 {
			fmt.Println(strings.Join(e.Editions, " "))
			return 0
		}
		release := ""
		if len(args) > 2 {
			release = args[2]
		}
		if eds := scrapeEditions(e.OS, release); len(eds) > 0 {
			fmt.Println(strings.Join(eds, " "))
		}
	}
	return 0
}

func cmdArch(cat *Catalog, args []string) int {
	{
		e := find(cat, args[1])
		if e == nil {
			return 1
		}
		if len(e.Arch) == 0 {
			fmt.Println("amd64")
		} else {
			fmt.Println(strings.Join(e.Arch, " "))
		}
	}
	return 0
}

func cmdURL(cat *Catalog, args []string) int {
	{
		e := find(cat, args[1])
		if e == nil {
			return 1
		}
		release, edition, arch := relArgs(args)
		if e.OS == "macos" {
			// get_macos show op: prints the raw recovery dmg link;
			// the caller pads it into the test_result label column.
			link, _ := macosRecoveryLink(release)
			fmt.Println(link)
			return 0
		}
		if e.Scrape {
			// Live resolution is native Go (scrape.go) — the scraper
			// mirrors the Bash get_<os> logic 1:1. No Bash delegation.
			full, hash, err := scrape(e.OS, release, edition, arch)
			if err != nil {
				// A get_* die() surfaces its ERROR! line on stdout and
				// the whole run exits 1.
				fmt.Printf("ERROR! %v\n", err)
				return 1
			}
			out := full
			if hash != "" {
				out = full + " " + hash
			}
			fmt.Println(out)
			return 0
		}
		full, hash := resolveURL(e, release, edition, arch)
		out := full
		if hash != "" {
			out = full + " " + hash
		}
		fmt.Println(out)
	}
	return 0
}

func cmdCheck(cat *Catalog, args []string) int {
	{
		// check <os> <release> [edition] [arch] — resolve the URL then
		// validate reachability like web_check: HEAD first, ranged GET
		// fallback (presigned URLs reject HEAD).
		e := find(cat, args[1])
		if e == nil {
			return 1
		}
		release, edition, arch := relArgs(args)
		label := e.OS + "-" + release
		if edition != "" {
			label += "-" + edition
		}
		if !archSupported(e, arch) {
			fmt.Printf("%s: %-35s (not available for %s)\n", "SKIP", label, arch)
			return 0
		}
		// windows/windows-server always SKIP in test mode — the gated
		// Microsoft flow can't be URL-probed (check.sh windows branch).
		if e.OS == "windows" || e.OS == "windows-server" {
			fmt.Printf("%s: %-35s %s\n", "SKIP", label, "")
			return 0
		}
		if e.OS == "macos" {
			// get_macos test op: recovery session → dmg link, then a
			// headered web_check (AssetToken cookie); prints PASS/FAIL.
			link, sess := macosRecoveryLink(release)
			res := "FAIL"
			if link != "" && qelib.WebCheck(link, map[string]string{
				"Host":       "oscdn.apple.com",
				"Connection": "close",
				"User-Agent": "InternetRecovery/1.0",
				"Cookie":     "AssetToken=" + sess,
			}) {
				res = "PASS"
			}
			fmt.Printf("%s: %-35s %s\n", res, label, link)
			return 0
		}
		full := ""
		if e.Scrape {
			// Resolution failures degrade to an empty URL like the
			// Bash $(get_*) capture — web_check "" fails → FAIL line,
			// the op still completes rc0. The diagnostic stays on stderr.
			f, _, err := scrape(e.OS, release, edition, arch)
			if err != nil {
				fmt.Fprintf(os.Stderr, "scrape:%s %v\n", e.OS, err)
			} else {
				full = f
			}
		} else {
			full, _ = resolveURL(e, release, edition, arch)
		}
		res := "FAIL"
		if webCheck(full) {
			res = "PASS"
		}
		fmt.Printf("%s: %-35s %s\n", res, label, full)
	}
	return 0
}

func cmdInfo(_ *Catalog, args []string) int {
	{
		// info <os> — PrettyName|Credentials|Homepage|Info (os_info parity)
		info, err := loadInfo(infoPath())
		if err != nil {
			fmt.Fprintf(os.Stderr, "info: %v\n", err)
			return 1
		}
		inf, ok := info[args[1]]
		if !ok {
			return 1
		}
		fmt.Printf("%s|%s|%s|%s\n", inf.Name, inf.Credentials, inf.Homepage, inf.Info)
	}
	return 0
}

func cmdMeta(cat *Catalog, args []string) int {
	{
		// meta [os] — classification metadata (status, image_type,
		// download_mode, license, boot_mode, support_level, arch).
		// No os → every entry, keyed by name.
		if len(args) > 1 {
			e := find(cat, args[1])
			if e == nil {
				return 1
			}
			b, _ := json.Marshal(e.meta())
			fmt.Println(string(b))
			return 0
		}
		all := make(map[string]Meta, len(cat.Entries))
		for i := range cat.Entries {
			all[cat.Entries[i].OS] = cat.Entries[i].meta()
		}
		b, _ := json.Marshal(all)
		fmt.Println(string(b))
	}
	return 0
}

func cmdInfoJSON(_ *Catalog, args []string) int {
	{
		info, err := loadInfo(infoPath())
		if err != nil {
			fmt.Fprintf(os.Stderr, "info: %v\n", err)
			return 1
		}
		b, _ := json.Marshal(info[args[1]])
		fmt.Println(string(b))
	}
	return 0
}

func cmdTrust(cat *Catalog, args []string) int {
	{
		// trust_os parity: resolve like get_<os> and report C when a
		// hash field comes back, D otherwise. No trust_<os> overrides
		// existed in Bash, so levels are only C/D (+E for misses).
		e := find(cat, args[1])
		if e == nil {
			fmt.Println("E")
			return 0
		}
		release, edition, arch := relArgs(args)
		fmt.Println(trustOf(e, release, edition, arch))
	}
	return 0
}

// trustOf resolves the entry like get_<os> and reports C when a hash
// field comes back, D otherwise (trust_os parity — a failed probe
// yields no hash, same as an empty get_* output in Bash).
func trustOf(e *Entry, release, edition, arch string) string {
	hash := ""
	if e.Scrape {
		_, hash, _ = scrape(e.OS, release, edition, arch)
	} else {
		_, hash = resolveURL(e, release, edition, arch)
	}
	if hash != "" {
		return "C"
	}
	return "D"
}
